<script setup lang="ts">
import { addBlob, checkSize } from '@tmt/browser-client'
import { ChevronDown, ChevronLeft, ChevronRight, CloudOff, FilePlus, FileText, Image, Link, Pencil, Star, Trash2, Upload, Users } from '@lucide/vue'
import { DEFAULT_MARKDOWN_CSS, type DocLink, applyTextDiff, buildLink, classify, createTextFile, deleteProjectFile, entryFile, getBlobs, getFiles, initializeProject, isEntryPath, isIgnored, keyAvatar, normalizePath, projectKind, renameProjectFile, setEntryFile } from '@tmt/shared'
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue'
import * as Y from 'yjs'
import { useToast } from '../lib/toast'; import { loadName, randomName, saveName } from '../lib/user'; import type { Project } from '../lib/project'; import { openProject } from '../lib/project'; import BlobView from './BlobView.vue'; import CodeEditor from './CodeEditor.vue'; import HtmlPreview from './HtmlPreview.vue'; import PromptDialog from './PromptDialog.vue'
const props = defineProps<{ link: DocLink }>(), toast = useToast(), project = shallowRef<Project | null>(null), current = ref<string | null>(null), entry = ref<string | null>(null), incompatible = ref(false), loading = ref(true), name = ref(loadName()), prompt = ref<InstanceType<typeof PromptDialog>>(), fileInput = ref<HTMLInputElement>(), mobileTab = ref<'source'|'preview'|'styles'>('source')
const paneKey = `tmt:md-panes:${props.link.docId}`; const saved = JSON.parse(localStorage.getItem(paneKey) ?? 'null') as { source?: boolean; preview?: boolean; styles?: boolean } | null; const panes = ref({ source: saved?.source ?? true, preview: saved?.preview ?? true, styles: saved?.styles ?? false })
let unmounted = false, update: (() => void) | undefined
openProject(props.link).then((p) => {
  if (unmounted) return p.destroy(); project.value = p
  if (sessionStorage.getItem(`tmt:init:${props.link.docId}`) === 'markdown') { sessionStorage.removeItem(`tmt:init:${props.link.docId}`); initializeProject(p.doc, 'markdown') }
  update = () => { const hasKind = p.doc.getMap('meta').has('kind'), kind = projectKind(p.doc); incompatible.value = (hasKind && kind !== 'markdown') || (!hasKind && p.status.value === 'synced'); entry.value = kind === 'markdown' && hasKind ? entryFile(p.doc, 'markdown') : null; loading.value = !hasKind && p.status.value !== 'synced' }
  p.doc.on('update', update); watch(p.status, update); update()
}, (e) => toast.error(`Could not open project: ${e}`))
onBeforeUnmount(() => { unmounted = true; if (project.value && update) project.value.doc.off('update', update); project.value?.destroy() })
const paths = computed(() => project.value?.paths.value ?? []), sourcePaths = computed(() => paths.value.filter((p) => p !== 'styles.css')), isText = (p: string) => !!project.value && getFiles(project.value.doc).has(p)
watch([sourcePaths, entry], () => { if (current.value && sourcePaths.value.includes(current.value)) return; current.value = entry.value ?? sourcePaths.value[0] ?? null })
function toggle(which: keyof typeof panes.value) { const open = Object.values(panes.value).filter(Boolean).length; if (panes.value[which] && open === 1) return; panes.value[which] = !panes.value[which]; localStorage.setItem(paneKey, JSON.stringify(panes.value)) }
function selectMobile(which: keyof typeof panes.value) { mobileTab.value = which; panes.value[which] = true }
function commitName() { name.value = name.value.trim() || randomName(); saveName(name.value); project.value?.setName(name.value) }
function validPath(value: string | null) { if (value == null) return null; const path = normalizePath(value); if (!path || isIgnored(path) || !classify(path)) { toast.error('Use a supported relative file path.'); return null } if (paths.value.includes(path)) { toast.error(`${path} already exists.`); return null } return path }
async function newFile() { const path = validPath(await prompt.value!.ask('New file', 'notes.md')); if (!path || !project.value) return; if (classify(path) !== 'text') return toast.error('Upload binary files instead.'); createTextFile(project.value.doc, path, ''); current.value = path; mobileTab.value = 'source' }
async function rename(from: string) { if (from === 'styles.css') return; const to = validPath(await prompt.value!.ask(`Rename ${from}`, from)); if (!to || !project.value) return; if (classify(to) !== classify(from)) return toast.error('Renaming cannot change between text and binary.'); renameProjectFile(project.value.doc, from, to); current.value = to }
function remove(path: string) { if (!project.value || path === 'styles.css' || !confirm(`Delete ${path}?`)) return; deleteProjectFile(project.value.doc, path) }
function choose(path: string) { if (path === 'styles.css') { panes.value.styles = true; mobileTab.value = 'styles' } else { current.value = path; mobileTab.value = 'source' }; (document.activeElement as HTMLElement | null)?.blur() }
function markEntry(path: string) { if (project.value && setEntryFile(project.value.doc, path)) entry.value = path }
async function addFiles(files: FileList | File[]) { if (!project.value) return; for (const file of files) { const path = normalizePath(file.name), kind = path && classify(path); if (!path || !kind) { toast.error(`${file.name}: unsupported file type.`); continue } const size = checkSize(file.size); if (size === 'too-big') { toast.error(`${file.name} is too large.`); continue } if (size === 'warn') toast.warning(`${file.name} is large; consider shrinking it.`); if (kind === 'text') { const text = await file.text(), existing = getFiles(project.value.doc).get(path); existing ? applyTextDiff(existing, text) : getFiles(project.value.doc).set(path, new Y.Text(text)) } else { try { await addBlob(project.value.link, project.value.doc, path, new Uint8Array(await file.arrayBuffer())) } catch (e) { toast.warning(`${file.name} saved locally; upload will retry.`) } } } }
function onPick(e: Event) { const input = e.target as HTMLInputElement; if (input.files) addFiles(input.files); input.value = '' }
async function copyLink() { const url = buildLink(location.origin + location.pathname, props.link); try { await navigator.clipboard.writeText(url); toast.success('Link copied.') } catch { await prompt.value?.ask('Copy this link', url) } }
const statusLabel = computed(() => project.value?.status.value === 'synced' ? 'Synced' : project.value?.status.value === 'syncing' ? 'Syncing' : 'Offline – changes are kept locally')
</script>
<template><div class="flex h-dvh flex-col">
  <header class="flex items-center gap-1 border-b border-base-300 px-2 py-1">
    <div class="dropdown"><button tabindex="0" class="btn btn-ghost btn-sm max-w-[32vw] font-normal"><span class="truncate">{{ current ?? 'No files' }}</span><ChevronDown class="size-4" /></button><ul tabindex="0" class="dropdown-content menu z-30 mt-1 w-80 max-w-[calc(100vw-1rem)] rounded-box bg-base-100 p-2 shadow"><li v-for="path in paths" :key="path"><div @click="choose(path)"><FileText v-if="isText(path)" class="size-4"/><Image v-else class="size-4"/><span class="flex-1 truncate">{{ path }}</span><Star v-if="path === entry" class="size-3.5 fill-current"/><button v-else-if="project && isEntryPath('markdown', path)" class="btn btn-ghost btn-xs btn-square" title="Set as entry" @click.stop="markEntry(path)"><Star class="size-3.5"/></button><button v-if="path !== 'styles.css'" class="btn btn-ghost btn-xs btn-square" title="Rename" @click.stop="rename(path)"><Pencil class="size-3.5"/></button><button v-if="path !== 'styles.css'" class="btn btn-ghost btn-xs btn-square" title="Delete" @click.stop="remove(path)"><Trash2 class="size-3.5"/></button></div></li><li><button @click="newFile"><FilePlus class="size-4"/>New file</button></li><li><button @click="fileInput?.click()"><Upload class="size-4"/>Upload files</button></li></ul></div><input ref="fileInput" type="file" multiple class="hidden" @change="onPick"/>
    <div class="flex-1"></div><span :title="statusLabel"><CloudOff v-if="project?.status.value === 'offline'" class="size-4 opacity-60"/><span v-else class="status" :class="project?.status.value === 'synced' ? 'status-success' : 'status-warning'"></span></span><span class="flex items-center gap-1 px-1 text-sm"><Users class="size-4"/>{{ project?.peers.value ?? 1 }}</span><img :src="keyAvatar(link.key)" class="size-6 rounded" alt=""/><input v-model="name" class="input input-ghost input-sm w-24 sm:w-40" @change="commitName" @keydown.enter="($event.target as HTMLInputElement).blur()"/><button class="btn btn-ghost btn-sm btn-square" title="Copy link" @click="copyLink"><Link class="size-4"/></button>
  </header>
  <div v-if="loading" class="flex flex-1 items-center justify-center"><span class="loading loading-spinner"></span></div><div v-else-if="incompatible" class="flex flex-1 items-center justify-center p-4 text-center"><div><h2 class="font-semibold">This is a Typst project</h2><p class="mt-2 opacity-60">Open it in the Typst frontend. The project was not changed.</p></div></div>
  <template v-else><div role="tablist" class="tabs tabs-border md:hidden"><button v-for="tab in (['source','preview','styles'] as const)" :key="tab" role="tab" class="tab flex-1 capitalize" :class="{'tab-active': mobileTab === tab}" @click="selectMobile(tab)">{{ tab }}</button></div>
  <main class="flex min-h-0 flex-1">
    <section v-if="panes.source" class="min-w-0 flex-1 flex-col border-r border-base-300 md:flex" :class="mobileTab === 'source' ? 'flex' : 'hidden'"><div class="hidden h-8 items-center border-b border-base-300 px-2 text-xs font-medium md:flex"><span class="flex-1">Source</span><button class="btn btn-ghost btn-xs btn-square" @click="toggle('source')"><ChevronLeft class="size-3.5"/></button></div><CodeEditor v-if="project && current && isText(current)" :project="project" :path="current" class="flex-1"/><BlobView v-else-if="project && current" :project="project" :path="current" class="flex-1"/><div v-else class="flex flex-1 items-center justify-center opacity-50">No source file</div></section><button v-else class="hidden w-8 border-r border-base-300 md:flex md:items-center md:justify-center" title="Open source" @click="toggle('source')"><ChevronRight class="size-4"/></button>
    <section v-if="panes.preview" class="min-w-0 flex-1 flex-col border-r border-base-300 md:flex" :class="mobileTab === 'preview' ? 'flex' : 'hidden'"><div class="hidden h-8 items-center border-b border-base-300 px-2 text-xs font-medium md:flex"><span class="flex-1">Preview</span><button class="btn btn-ghost btn-xs btn-square" @click="toggle('preview')"><ChevronLeft class="size-3.5"/></button></div><HtmlPreview v-if="project" :project="project" :entry="entry" class="flex-1"/></section><button v-else class="hidden w-8 border-r border-base-300 md:flex md:items-center md:justify-center" title="Open preview" @click="toggle('preview')"><ChevronRight class="size-4"/></button>
    <section v-if="panes.styles" class="min-w-0 flex-1 flex-col md:flex" :class="mobileTab === 'styles' ? 'flex' : 'hidden'"><div class="hidden h-8 items-center border-b border-base-300 px-2 text-xs font-medium md:flex"><span class="flex-1">styles.css</span><button class="btn btn-ghost btn-xs btn-square" @click="toggle('styles')"><ChevronRight class="size-3.5"/></button></div><CodeEditor v-if="project && getFiles(project.doc).has('styles.css')" :project="project" path="styles.css" class="flex-1"/><button v-else class="btn m-auto" @click="project && createTextFile(project.doc, 'styles.css', DEFAULT_MARKDOWN_CSS)">Create styles.css</button></section><button v-else class="hidden w-8 md:flex md:items-center md:justify-center" title="Open styles" @click="toggle('styles')"><ChevronLeft class="size-4"/></button>
  </main></template><PromptDialog ref="prompt"/></div></template>
